CREATE    VIEW [FO].[vwCustInvoice] AS

	WITH LT AS (
	SELECT 
	SUBLEDGERVOUCHER
	,MIN(RICSCOUNTRY) AS COUNTRY
	,MIN(RICSPROJECT) AS Project
	FROM synapse_fo.LEDGERTRANS_RICS LT
	GROUP BY SUBLEDGERVOUCHER
	)

	SELECT 
	 CAST(NULL AS BIGINT) AS [SysRowId]
	,CIT.[SALESID] AS Order_Number
	--,CIT.[TAXGROUP]
	,CIT.[CURRENCYCODE] AS Currency
	,CAST(CIT.[INVOICEDATE] AS DATE) AS Invoice_Date
	,CIT.[INVOICEID] AS Invoice_ID
	,CIJ.LEDGERVOUCHER AS Voucher
	,CIJ.ORDERACCOUNT AS Customer_Account
	,CIJ.INVOICEACCOUNT AS Invoice_Account
	--,CIT.[DEFAULTDIMENSION]
	--,CIT.[DELIVERYPOSTALADDRESS]
	--,CIT.[DISCAMOUNT]
	--,CIT.[DLVDATE]
	--,CIT.[INVENTTRANSID]
	,CIT.[ITEMID] AS Product_Code
	,LT.[Project]	
	--,CIT.[LEDGERDIMENSION]
	,CIT.[LINEAMOUNT] AS Line_Amount_CUR
	,CIT.[LINEAMOUNTMST] AS Line_Amount_GBP
	--,CIT.[LINEHEADER]
	--,CIT.[LINENUM]
	,CIT.[NAME] AS 'Description'
	--,CIT.[ORIGSALESID]
	--,CIT.[PARENTRECID]
	--,CIT.[PRICEUNIT]
	--,CIT.[QTY]
	--,CIT.[QTYPHYSICAL]
	--,CIT.[REASONREFRECID]
	--,CIT.[SALESMARKUP]
	--,CIT.[SALESPRICE]
	--,CIT.[SOURCEDOCUMENTLINE]
	--,CIT.[TAXITEMGROUP]
	--,CIT.[TAXWRITECODE]
	,UPPER(CIT.[DATAAREAID]) AS Date_Area_ID
	--,CIT.[PARTITION]
	--,CIT.[RECID]
	,CIT.[MODIFIEDDATETIME] AS 'Modified_Datetime'
	,CIT.[CREATEDDATETIME] AS 'Created_Datetime'
	--,CIT.[CREATEDBY]
	--,CIT.[REVRECREVENUESCHEDULEID]
	--,CIT.[REVRECDEFERRED]
	--,CIT.[REVRECDEFERREDPROCESSED]
	--,GJE.RECID AS GJE_Rec_ID
	,LT.COUNTRY AS Country_Code
	,OwnerIdName AS 'Owner'
	FROM [synapse_fo].[CUSTINVOICETRANS] CIT
	LEFT JOIN [synapse_fo].[CUSTINVOICEJOUR] CIJ
		ON CIT.INVOICEID = CIJ.INVOICEID
		AND COALESCE(CIT.SALESID, '') = COALESCE(CIJ.SALESID, '')
		AND CIT.INVOICEDATE = CIJ.INVOICEDATE
		AND CIT.DATAAREAID = CIJ.DATAAREAID
	LEFT JOIN LT LT
		ON CIJ.LEDGERVOUCHER = LT.SUBLEDGERVOUCHER
	LEFT JOIN synapse_ce.salesorder SOO
		ON REPLACE(SOO.ordernumber, 'rcs', '')  = CIJ.SALESID
